python3 -c "import ast, pathlib, sys
failed = []
for p in pathlib.Path('/app/gradio').glob('*.py'):
    try:
        ast.parse(p.read_text(encoding='utf-8'))
    except SyntaxError as exc:
        failed.append(f'{p}: {exc}')
if failed:
    print('SYNTAX_FAIL')
    print('\n'.join(failed))
    sys.exit(1)
print('GRADIO_SYNTAX_OK')"
